export function UncontrolledComponent({
  inputLabel = "{{inputLabel}}",
  defaultValue = "{{defaultValue}}",
  showRefNote = {{showRefNote}},
  accent = "{{accent}}",
}) {
  return (
    <div style={{ font: "13px/1.5 system-ui, sans-serif", color: "#241430", background: "#FAF7F2", padding: 18, borderRadius: 12, width: 280, boxSizing: "border-box" }}>
      <label style={{ display: "block", fontSize: 11, fontWeight: 600, marginBottom: 4 }}>{inputLabel}</label>
      <input type="text" defaultValue={defaultValue}
        style={{ width: "100%", boxSizing: "border-box", padding: "8px 10px", border: `2px solid ${accent}`, borderRadius: 6, fontSize: 13, background: "#ffffff", color: "#241430" }} />
      <p style={{ margin: "8px 0 0", fontSize: 10, color: "#24143099" }}>Editable freely &mdash; the DOM node owns this value.{showRefNote && " A parent can only read it later via a ref."}</p>
    </div>
  );
}
